// Node-side stub of BufferGeometryUtils, mirroring the three/index.mjs stub:
// the browser loads the real file from the CDN through the import map in
// index.html, while Node has no import map, so chibi.js's bare-specifier
// import needs something resolvable here or every suite that imports
// characters.js dies at module load.
//
// No test under Node calls build(), so mergeGeometries is never exercised in
// anger here. It is still a real merge rather than a throw, so a future test
// that does build a character gets sane output instead of a crash: indexed
// and non-indexed geometries are concatenated per attribute, with the index
// offsets shifted per source geometry.

export function mergeGeometries(geometries) {
  if (!geometries || geometries.length === 0) return null;
  if (geometries.length === 1) return geometries[0];

  const attrs = {};
  const first = geometries[0];
  for (const name of Object.keys(first.attributes)) {
    const itemSize = first.attributes[name].itemSize || 3;
    const ArrayCtor = first.attributes[name].array.constructor;
    let total = 0;
    for (const g of geometries) total += g.attributes[name]?.array.length || 0;
    const out = new ArrayCtor(total);
    let o = 0;
    for (const g of geometries) {
      const a = g.attributes[name]?.array;
      if (a) { out.set(a, o); o += a.length; }
    }
    attrs[name] = { array: out, itemSize };
  }

  let index = null;
  if (first.index) {
    const Ctor = first.index.array.constructor;
    let total = 0;
    for (const g of geometries) total += g.index ? g.index.array.length : vertexCount(g);
    index = new Ctor(total);
    let o = 0, offset = 0;
    for (const g of geometries) {
      const n = vertexCount(g);
      if (g.index) {
        for (let i = 0; i < g.index.array.length; i++) index[o + i] = g.index.array[i] + offset;
        o += g.index.array.length;
      } else {
        for (let i = 0; i < n; i++) index[o + i] = i + offset;
        o += n;
      }
      offset += n;
    }
  }

  return { attributes: attrs, index: index ? { array: index } : null };
}

function vertexCount(g) {
  const p = g.attributes?.position;
  return p ? p.array.length / (p.itemSize || 3) : 0;
}
